{
  "hypotheses": [
    {
      "claim": "When a promise with a cancel method times out and fallback is not provided, the cancel method is called before rejecting with TimeoutError",
      "path": "index.js",
      "start_line": 70,
      "end_line": 82,
      "evidence": "if (typeof promise.cancel === 'function') {
			promise.cancel();
		}

		if (message === false) {
			resolve();
		} else if (message instanceof Error) {
			reject(message);
		} else {
			timeoutError.message = message ?? `Promise timed out after ${milliseconds} milliseconds`;
			reject(timeoutError);
		}",
      "reproduction": {
        "code": "const {default: pTimeout, TimeoutError} = await load('./index.js');

const cancelSpy = jest.fn();
const inputPromise = Promise.resolve('success');
inputPromise.cancel = cancelSpy;

const decoratedPromise = pTimeout(inputPromise, {milliseconds: 10});

setTimeout(() => {
  decoratedPromise.clear();
}, 5);

try {
  await decoratedPromise;
} catch (error) {
  assert.ok(error instanceof TimeoutError);
  assert.equal(cancelSpy.mock.calls.length, 1);
}"
